import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class Main {
    static final class Bag<T> implements Iterable<T> {
        private final List<T> values = new ArrayList<>();
        public void add(T value) { values.add(value); }
        public int size() { return values.size(); }
        @Override public Iterator<T> iterator() { return values.iterator(); }
    }
    public static void main(String[] args) {
        Bag<String> bag = new Bag<>();
        bag.add("Java"); bag.add("SQL");
        for (String value : bag) System.out.println(value);
        System.out.println("size=" + bag.size());
    }
}
